<?php
if (!defined('ABSPATH')) exit;
function gim_schema_sql(){ global $wpdb; $c=$wpdb->get_charset_collate(); $p=$wpdb->prefix.'gim_'; return [
"CREATE TABLE {$p}providers (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,public_id VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending',business_name VARCHAR(190) NOT NULL DEFAULT '',trade_family VARCHAR(60) NOT NULL DEFAULT '',services_json LONGTEXT NULL,coverage_json LONGTEXT NULL,verification_json LONGTEXT NULL,stripe_account_id VARCHAR(120) NULL,stripe_ready TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY user_id(user_id),UNIQUE KEY public_id(public_id)) $c;",
"CREATE TABLE {$p}jobs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,reference VARCHAR(40) NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,provider_id BIGINT UNSIGNED NULL,service_slug VARCHAR(120) NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'draft',urgency VARCHAR(20) NOT NULL DEFAULT 'standard',description TEXT NOT NULL,postcode VARCHAR(20) NOT NULL DEFAULT '',scheduled_at DATETIME NULL,vji_status VARCHAR(32) NOT NULL DEFAULT 'pending',vji_digest VARCHAR(128) NULL,evidence_json LONGTEXT NULL,meta_json LONGTEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY reference(reference),KEY customer(customer_id),KEY provider(provider_id),KEY status(status)) $c;",
"CREATE TABLE {$p}job_requests (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,job_id BIGINT UNSIGNED NOT NULL,provider_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'sent',created_at DATETIME NOT NULL,responded_at DATETIME NULL,PRIMARY KEY(id),UNIQUE KEY one_provider_job(job_id,provider_id)) $c;",
"CREATE TABLE {$p}estimates (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,reference VARCHAR(40) NOT NULL,job_id BIGINT UNSIGNED NOT NULL,provider_id BIGINT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'sent',revision_no INT NOT NULL DEFAULT 1,items_json LONGTEXT NOT NULL,service_subtotal_pence BIGINT NOT NULL DEFAULT 0,materials_subtotal_pence BIGINT NOT NULL DEFAULT 0,total_pence BIGINT NOT NULL DEFAULT 0,digest VARCHAR(128) NOT NULL,created_at DATETIME NOT NULL,decided_at DATETIME NULL,PRIMARY KEY(id),UNIQUE KEY reference(reference),KEY job_id(job_id)) $c;",
"CREATE TABLE {$p}payments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,reference VARCHAR(40) NOT NULL,job_id BIGINT UNSIGNED NOT NULL,estimate_id BIGINT UNSIGNED NULL,additional_work_id BIGINT UNSIGNED NULL,purpose VARCHAR(40) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'created',amount_pence BIGINT NOT NULL,currency VARCHAR(8) NOT NULL DEFAULT 'gbp',stripe_session_id VARCHAR(255) NULL,stripe_payment_intent_id VARCHAR(255) NULL,refunded_pence BIGINT NOT NULL DEFAULT 0,meta_json LONGTEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY reference(reference),KEY job_id(job_id),KEY stripe_session(stripe_session_id)) $c;",
"CREATE TABLE {$p}materials (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,job_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'not_required',quoted_pence BIGINT NOT NULL DEFAULT 0,actual_pence BIGINT NOT NULL DEFAULT 0,invoice_file VARCHAR(255) NULL,invoice_hash VARCHAR(128) NULL,lines_json LONGTEXT NULL,ai_decision VARCHAR(40) NULL,ai_score INT NULL,ai_findings_json LONGTEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY job_id(job_id)) $c;",
"CREATE TABLE {$p}additional_work (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,reference VARCHAR(40) NOT NULL,job_id BIGINT UNSIGNED NOT NULL,provider_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'proposed',reason TEXT NOT NULL,items_json LONGTEXT NOT NULL,service_pence BIGINT NOT NULL DEFAULT 0,materials_pence BIGINT NOT NULL DEFAULT 0,digest VARCHAR(128) NOT NULL,created_at DATETIME NOT NULL,decided_at DATETIME NULL,PRIMARY KEY(id),UNIQUE KEY reference(reference),KEY job_id(job_id)) $c;",
"CREATE TABLE {$p}disputes (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,reference VARCHAR(40) NOT NULL,job_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,provider_id BIGINT UNSIGNED NULL,status VARCHAR(40) NOT NULL DEFAULT 'open',reason TEXT NOT NULL,customer_evidence_json LONGTEXT NULL,provider_response TEXT NULL,provider_evidence_json LONGTEXT NULL,resolution VARCHAR(50) NULL,refund_pence BIGINT NOT NULL DEFAULT 0,admin_notes TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY reference(reference),KEY job_id(job_id),KEY status(status)) $c;",
"CREATE TABLE {$p}cancellations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,reference VARCHAR(40) NOT NULL,job_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'requested',reason TEXT NULL,refund_pence BIGINT NOT NULL DEFAULT 0,retained_pence BIGINT NOT NULL DEFAULT 0,policy_json LONGTEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY reference(reference),UNIQUE KEY job_id(job_id)) $c;",
"CREATE TABLE {$p}reviews (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,job_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,provider_id BIGINT UNSIGNED NOT NULL,rating TINYINT NOT NULL,quality TINYINT NULL,reliability TINYINT NULL,communication TINYINT NULL,value_rating TINYINT NULL,body TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'published',created_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY one_review(job_id,customer_id)) $c;",
"CREATE TABLE {$p}assurance_runs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,job_id BIGINT UNSIGNED NOT NULL,engine_version VARCHAR(40) NOT NULL,decision VARCHAR(30) NOT NULL,risk_score INT NOT NULL,input_digest VARCHAR(128) NOT NULL,output_digest VARCHAR(128) NOT NULL,findings_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(id),KEY job_id(job_id)) $c;",
"CREATE TABLE {$p}risk_runs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,job_id BIGINT UNSIGNED NOT NULL,engine_version VARCHAR(40) NOT NULL,risk_score INT NOT NULL,risk_level VARCHAR(20) NOT NULL,findings_json LONGTEXT NOT NULL,safeguards_json LONGTEXT NOT NULL,input_digest VARCHAR(128) NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(id),KEY job_id(job_id)) $c;",
"CREATE TABLE {$p}payouts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,reference VARCHAR(40) NOT NULL,job_id BIGINT UNSIGNED NOT NULL,provider_id BIGINT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'requested',gross_pence BIGINT NOT NULL DEFAULT 0,platform_fee_pence BIGINT NOT NULL DEFAULT 0,provider_pence BIGINT NOT NULL DEFAULT 0,stripe_transfer_id VARCHAR(255) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY reference(reference),KEY job_id(job_id),KEY provider_id(provider_id)) $c;",
"CREATE TABLE {$p}outcome_runs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,provider_id BIGINT UNSIGNED NOT NULL,service_slug VARCHAR(120) NOT NULL,engine_version VARCHAR(40) NOT NULL,outcome_score DECIMAL(6,2) NOT NULL,confidence_score DECIMAL(6,2) NOT NULL,confidence_level VARCHAR(20) NOT NULL,sample_size INT NOT NULL,signals_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(id),KEY provider_service(provider_id,service_slug)) $c;",
"CREATE TABLE {$p}audit (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,actor_user_id BIGINT UNSIGNED NULL,actor_role VARCHAR(30) NOT NULL,event_type VARCHAR(100) NOT NULL,entity_type VARCHAR(50) NULL,entity_ref VARCHAR(80) NULL,data_json LONGTEXT NULL,ip_hash VARCHAR(128) NULL,created_at DATETIME NOT NULL,PRIMARY KEY(id),KEY event_type(event_type),KEY entity_ref(entity_ref)) $c;"
]; }
function gim_install_tables(){ require_once ABSPATH.'wp-admin/includes/upgrade.php'; foreach(gim_schema_sql() as $sql) dbDelta($sql); update_option('gim_schema_version',GIM_VERSION); }
